private static String substitute(String value, Properties props) {
    Pattern varPat = Pattern.compile("(\\$\\{[^}]+\\})");
    Matcher matcher = varPat.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String varName = matcher.group(1).substring(2, matcher.group(1).length() - 1);
        if (props.containsKey(varName)) {
            matcher.appendReplacement(sb, Matcher.quoteReplacement(props.getProperty(varName)));
        } else {
            matcher.appendReplacement(sb, "");
        }
    }
    matcher.appendTail(sb);
    return sb.toString();
}
