/**
 * A circulator that iterates over nodes in the graph in a circular fashion, starting and ending at the same node. The direction of traversal can be specified using the {@code dir} parameter.
 */
private class OuterFaceCirculator implements CircularIterator {

    private Node currentNode;
    private Node nextNode;
    private int direction;

    public OuterFaceCirculator(Node start, int dir) {
        this.currentNode = start;
        this.nextNode = start;
        this.direction = dir;
    }

    @Override
    public boolean hasNext() {
        return true;
    }

    @Override
    public Node next() {
        if (direction > 0) {
            nextNode = currentNode.getNextSibling();
        } else {
            nextNode = currentNode.getPreviousSibling();
        }
        return nextNode;
    }
}

